#include <vector>
#include <unordered_map>

class Solution {
public:
    int minSwapsToEqualize(std::vector<int>& nums1, std::vector<int>& nums2) {
        std::unordered_map<int, int> c1, total;
        for (int x : nums1) { c1[x]++; total[x]++; }
        for (int x : nums2) total[x]++;
        for (const auto& [k, v] : total) {
            if (v % 2 != 0) return -1;
        }
        int diff = 0;
        for (const auto& [k, v] : total) {
            int target = v / 2;
            int count1 = c1.count(k) ? c1[k] : 0;
            if (count1 > target) diff += count1 - target;
        }
        return diff;
    }
};

import java.util.*;

class Solution {
    public int minSwapsToEqualize(int[] nums1, int[] nums2) {
        Map<Integer, Integer> c1 = new HashMap<>();
        Map<Integer, Integer> total = new HashMap<>();
        for (int x : nums1) {
            c1.put(x, c1.getOrDefault(x, 0) + 1);
            total.put(x, total.getOrDefault(x, 0) + 1);
        }
        for (int x : nums2) {
            total.put(x, total.getOrDefault(x, 0) + 1);
        }
        for (var entry : total.entrySet()) {
            if (entry.getValue() % 2 != 0) return -1;
        }
        int diff = 0;
        for (var entry : total.entrySet()) {
            int target = entry.getValue() / 2;
            int count1 = c1.getOrDefault(entry.getKey(), 0);
            if (count1 > target) diff += count1 - target;
        }
        return diff;
    }
}

